export const code = async (inputs) => {
  const months = Number(inputs.months);
  const today = new Date(inputs.today);

  const ranges = [];

  // Calculate the starting date
  const lookbackDate = new Date(today);
  lookbackDate.setMonth(lookbackDate.getMonth() - months);

  // Generate one date window per month
  let currentStart = new Date(lookbackDate);

  while (currentStart < today) {
    const currentEnd = new Date(currentStart);
    currentEnd.setMonth(currentEnd.getMonth() + 1);

    // Don't go beyond today
    if (currentEnd > today) {
      currentEnd.setTime(today.getTime());
    }

    ranges.push({
      after: currentStart.toISOString().split('T')[0],
      before: currentEnd.toISOString().split('T')[0]
    });

    currentStart = new Date(currentEnd);
  }

  return {
    today: today.toISOString().split('T')[0],
    months,
    lookbackDate: lookbackDate.toISOString().split('T')[0],
    ranges
  };
};

export const code = async (inputs) => {
  const messages = inputs.data.results.messages;

  const attachmentMails = messages
    .filter((mail) => mail.attachments?.length > 0)
    .map((mail) => ({
      messageId: mail.id,
      subject: mail.subject,
      subject: mail.subject,
      from: mail.from?.value?.[0]?.address,
      date: mail.date,
      attachments: mail.attachments
    }));

  const oldestDate = messages.length > 0
    ? messages.reduce((oldest, mail) => {
        return new Date(mail.date) < new Date(oldest)
          ? mail.date
          : oldest;
      }, messages[0].date)
    : null;

  const formattedOldestDate = oldestDate
    ? new Date(oldestDate).toISOString().split('T')[0]
    : null;

  return {
    attachmentMails,
    oldestDate: formattedOldestDate
  };
};

