export const code = async (inputs) => {
  const raw = inputs.receiver;

  if (Array.isArray(raw)) return { receiver: raw };

  const match = raw.match(/<([^>]+)>/);
  const email = match ? match[1] : raw.trim();

  return { receiver: [email] };
};

export const code = async (inputs) => {
  const item = inputs.item;

  if (!item || typeof item !== 'object') {
    return {
      hasRealAttachment: false,
      attachment: null,
      reason: 'no email item found'
    };
  }

  const attachments = Array.isArray(item.attachments)
    ? item.attachments
    : [];

  const junkTypes = ['image/gif', 'text/calendar', 'text/x-vcard'];
  const junkExtensions = ['.ics', '.vcf'];

  const realAttachments = attachments.filter((attachment) => {
    if (!attachment || typeof attachment !== 'object') {
      return false;
    }

    if (junkTypes.some(t => attachment.mimeType?.includes(t))) {
      return false;
    }

    if (junkExtensions.some(e => attachment.fileName?.toLowerCase().endsWith(e))) {
      return false;
    }

    return true;
  });

  if (realAttachments.length === 0) {
    return {
      hasRealAttachment: false,
      attachment: null,
      reason: 'no real attachments found'
    };
  }

  return {
    hasRealAttachment: true,
    attachments: realAttachments.map((attachment) => ({
      messageId: item.messageId,
      fileName: attachment.fileName,
      mimeType: attachment.mimeType,
      size: attachment.size,
      data: attachment.data,
      subject: item.subject,
      from: item.from,
      date: item.date
    }))
  };
};

export const code = async (inputs) => {
  const crypto = require('crypto');
  const https = require('https');

  const fetchBuffer = (url) => new Promise((resolve, reject) => {
    const fetch = (u) => {
      const urlObj = new URL(u);
      const options = {
        hostname: urlObj.hostname,
        path: urlObj.pathname + urlObj.search,
        method: 'GET',
        headers: { 'User-Agent': 'Node.js' }
      };
      https.request(options, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          fetch(res.headers.location);
          return;
        }
        const chunks = [];
        res.on('data', chunk => chunks.push(chunk));
        res.on('end', () => resolve(Buffer.concat(chunks)));
        res.on('error', reject);
      }).on('error', reject).end();
    };
    fetch(url);
  });

  const isPasswordProtected = (buffer, mimeType) => {
    const str = buffer.toString('binary');

    // PDF — /Encrypt dictionary is only present when encrypted
    if (mimeType === 'application/pdf' || str.startsWith('%PDF')) {
      return str.includes('/Encrypt');
    }

    // CFB/OLE container — not all CFB files are encrypted
    // Only encrypted ones contain the WorkbookProtection or DocumentProtection
    // stream, or the EncryptionInfo entry in the directory
    if (buffer[0] === 0xD0 && buffer[1] === 0xCF && buffer[2] === 0x11 && buffer[3] === 0xE0) {
      return (
        str.includes('EncryptionInfo') ||
        str.includes('StrongEncryptionDataSpace') ||
        str.includes('\x45\x00\x6E\x00\x63\x00\x72\x00\x79\x00\x70\x00\x74\x00') // "Encrypt" in UTF-16LE
      );
    }

    // Zip-based Office (docx, xlsx, pptx)
    if (str.startsWith('PK')) {
      return str.includes('EncryptionInfo') || str.includes('EncryptedPackage');
    }

    return false;
  };

  const buffer = await fetchBuffer(inputs.fileUrl);
  const hash = crypto.createHash('sha256').update(buffer).digest('hex');
  const passwordProtected = isPasswordProtected(buffer, inputs.mimeType);

  return { hash, passwordProtected };
};

export const code = async (inputs) => {
  const currentHash = inputs.hash;
  const allRows = inputs.rows;

  const matchIndex = allRows.findIndex(r =>
    r.values['Hash-code'] === currentHash &&
    currentHash !== '' &&
    currentHash !== null
  );

  const isDuplicate = matchIndex !== -1;

  return {
    isDuplicate,
    rowNumber: isDuplicate ? matchIndex + 1 : null
  };
};

