export const code = async (inputs) => {
  const data = inputs.data;

  // Handles both:
  // inputs.data.item
  // and inputs.data directly being the item
  const message = data?.item ?? data;

  const attachment = message?.attachments?.[0];

  if (!message) {
    throw new Error('No message data found');
  }

  if (!attachment) {
    throw new Error('No attachment found');
  }

  const raw = (inputs.aiOutput || '')
    .replace(/```json|```/g, '')
    .trim();

  const classification = JSON.parse(raw);

  // Date
  let date;
  try {
    date = new Date(message.date);
    if (isNaN(date.getTime())) throw new Error();
  } catch {
    date = new Date();
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');

  const clean = (str) => (str || 'Unknown')
    .replace(/[^a-zA-Z0-9 ]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .slice(0, 30);

  const sender = clean(message.from);
  const fileType = clean(
    (attachment.mimeType || 'unknown').split('/')[1]
  );
  const docType = clean(classification.type || 'Unknown');

  return {
    folderName: `${sender}_${year}-${month}_${fileType}_${docType}`,
    fileName: attachment.fileName
  };
};

